// Generated by scripts/bundle-content.mjs. Do not edit by hand.
// ---- extension/lib/eligibility.js ----
// Eligibility engine (M3): pure sounded-time tracker. No timers, no I/O, no DOM.
// Locked rule (GLOSSARY Eligible listen): eligible once per track ID when sounded time
// reaches max(durationMs * thresholdRatio, minSoundedMs). Pauses and seeks never
// credit because callers feed ONLY actually-sounded deltas through sound().
// A tracker instance covers one listening session; reset() starts a new session.

class EligibilityTracker {
  constructor({ thresholdRatio = 0.9, minSoundedMs = 60000 } = {}) {
    this.thresholdRatio = thresholdRatio;
    this.minSoundedMs = minSoundedMs;
    this.reset();
  }

  reset() {
    this.currentTrackId = null;
    this.currentDurationMs = 0;
    this.soundedMs = 0;
    this.consumedTrackIds = new Set();
  }

  // Feed actually-sounded audio time for a track. Returns true exactly once per
  // trackId, on the transition to eligible. Invalid input never credits, never throws.
  sound(trackId, durationMs, deltaSoundedMs) {
    if (!trackId || !(durationMs > 0) || !(deltaSoundedMs > 0)) return false;
    if (trackId !== this.currentTrackId) {
      this.currentTrackId = trackId;
      this.currentDurationMs = durationMs;
      this.soundedMs = 0;
    }
    if (this.consumedTrackIds.has(trackId)) return false;
    this.soundedMs += deltaSoundedMs;
    const threshold = Math.max(
      this.currentDurationMs * this.thresholdRatio,
      this.minSoundedMs,
    );
    if (this.soundedMs >= threshold) {
      this.consumedTrackIds.add(trackId);
      return true;
    }
    return false;
  }
}


// ---- extension/lib/settings.js ----
// Settings model (M5): defaults, validation, and storage for the three locked
// options (threshold, floor, enable-disable). Pure logic with an injected store;
// the options page UI lands with the extension shell and only reads/writes here.

const DEFAULTS = Object.freeze({
  thresholdRatio: 0.9,
  minSoundedMs: 60_000,
  enabled: true,
});

function thresholdOrDefault(v) {
  return typeof v === "number" && Number.isFinite(v) && v > 0 && v <= 1 ? v : DEFAULTS.thresholdRatio;
}

function floorOrDefault(v) {
  return typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : DEFAULTS.minSoundedMs;
}

function normalizeSettings(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  return {
    thresholdRatio: thresholdOrDefault(source.thresholdRatio),
    minSoundedMs: floorOrDefault(source.minSoundedMs),
    enabled: typeof source.enabled === "boolean" ? source.enabled : DEFAULTS.enabled,
  };
}

async function loadSettings(store) {
  return normalizeSettings(await store.load());
}

async function saveSettings(store, patch) {
  const next = normalizeSettings({ ...(await store.load()), ...patch });
  await store.save(next);
  return next;
}


// ---- extension/lib/player-dom.js ----
// Spotify web-player DOM boundary (M2/M4). Sole module that reads the
// open.spotify.com player or clicks its Like controls. Everything else
// works with TrackIdentity, PlaybackSample, and LikeState values.

const SELECTORS = Object.freeze({
  widget: '[data-testid="now-playing-widget"]',
  title: '[data-testid="context-item-info-title"]',
  link: '[data-testid="context-item-link"]',
  artist: '[data-testid="context-item-info-artist"]',
  trackAnchor: 'a[data-testid="context-link"][data-context-item-type="track"]',
  playPause: '[data-testid="control-button-playpause"]',
  progressBar: '[data-testid="playback-progressbar"]',
  positionText: '[data-testid="playback-position"]',
  durationText: '[data-testid="playback-duration"]',
  nowPlayingView: 'aside[aria-label="Now playing view"]',
  adBar: '[data-testadtype]',
  adWidget: '[data-testid="now-playing-widget-v2"]',
  menu: '[data-testid="context-menu"]',
  likedRow: '[aria-labelledby="listrow-title-spotify:collection:tracks"]',
});

function textOf(root, selector) {
  let node = null;
  try {
    node = root.querySelector(selector);
  } catch (e) {
    return "";
  }
  return (node && node.textContent ? node.textContent : "").trim();
}

function attrOf(node, name) {
  try {
    return node && node.getAttribute ? (node.getAttribute(name) || null) : null;
  } catch (e) {
    return null;
  }
}

function parseTimeToMs(value) {
  const parts = String(value || "").trim().split(":");
  if (parts.length < 1 || parts.length > 3) return NaN;
  const nums = parts.map((p) => Number(p));
  if (nums.some((n) => !Number.isFinite(n) || n < 0)) return NaN;
  let total = 0;
  for (const n of nums) total = total * 60 + n;
  return Math.round(total * 1000);
}

const TRACK_ID_PATTERNS = [
  /spotify:track:([A-Za-z0-9]+)/,
  /spotify%3Atrack%3A([A-Za-z0-9]+)/i,
];

function extractTrackId(candidate) {
  if (!candidate) return null;
  for (const pattern of TRACK_ID_PATTERNS) {
    const match = String(candidate).match(pattern);
    if (match) return match[1];
  }
  return null;
}

function matchesTitle(anchor, title) {
  const label = rowLabel(anchor).toLowerCase();
  const expected = String(title || "").trim().toLowerCase();
  if (!label) return true;
  return !!expected && (label.includes(expected) || expected.includes(label));
}

function anchorTrackId(anchor) {
  for (const name of ["href", "data-uri", "data-context-uri"]) {
    const id = extractTrackId(attrOf(anchor, name));
    if (id) return id;
  }
  return null;
}

function findTrackAnchor(doc, widget, title) {
  const selectors = [
    SELECTORS.trackAnchor,
    'a[href*="spotify:track:"]',
    'a[href*="spotify%3Atrack%3A"]',
  ];
  let view = null;
  try {
    view = doc.querySelector(SELECTORS.nowPlayingView);
  } catch (e) {
    view = null;
  }
  const roots = [widget, view, doc].filter(Boolean);
  for (const root of roots) {
    for (const selector of selectors) {
      let nodes = [];
      try {
        nodes = root.querySelectorAll
          ? root.querySelectorAll(selector)
          : [root.querySelector(selector)];
      } catch (e) {
        continue;
      }
      for (const node of nodes) {
        if (anchorTrackId(node) && (root === widget || matchesTitle(node, title))) return node;
      }
    }
  }
  return null;
}

function readTrack(doc) {
  if (readAdType(doc)) return null;
  let widget = null;
  try {
    widget = doc.querySelector(SELECTORS.widget);
  } catch (e) {
    return null;
  }
  if (!widget) return null;
  const title = textOf(widget, SELECTORS.title) || textOf(doc, SELECTORS.title);
  const artist = textOf(widget, SELECTORS.artist) || textOf(doc, SELECTORS.artist);
  if (!title || !artist) return null;
  const anchor = findTrackAnchor(doc, widget, title);
  const trackId = anchorTrackId(anchor);
  if (!trackId) return null;
  return { id: trackId, uri: "spotify:track:" + trackId, title, artist };
}

function findRangeInput(doc) {
  try {
    const direct = doc.querySelector(SELECTORS.progressBar + ' input[type="range"]');
    if (direct) return direct;
  } catch (e) {
    // Fall through to the structural lookup below.
  }
  let bar = null;
  try {
    bar = doc.querySelector(SELECTORS.progressBar);
  } catch (e) {
    bar = null;
  }
  try {
    return (bar && bar.querySelector && bar.querySelector("input")) || null;
  } catch (e) {
    return null;
  }
}

function rangeMs(range) {
  const positionMs = Number(range && range.value);
  const durationMs = Number(range && range.max);
  if (Number.isFinite(positionMs) && Number.isFinite(durationMs) && durationMs > 0) {
    return { positionMs: Math.max(0, positionMs), durationMs };
  }
  return null;
}

function readTimes(doc) {
  const fromRange = rangeMs(findRangeInput(doc));
  if (fromRange) return fromRange;
  const positionMs = parseTimeToMs(textOf(doc, SELECTORS.positionText));
  const durationMs = parseTimeToMs(textOf(doc, SELECTORS.durationText));
  if (!Number.isFinite(positionMs) || !Number.isFinite(durationMs) || durationMs <= 0) return null;
  return { positionMs, durationMs };
}

function hasPlayer(doc) {
  for (const selector of [SELECTORS.widget, SELECTORS.playPause]) {
    try {
      if (doc.querySelector(selector)) return true;
    } catch (e) {
      continue;
    }
  }
  return false;
}

function findLikeControl(doc) {
  try {
    return doc.querySelector(SELECTORS.widget + " button[aria-checked]")
      || doc.querySelector("button[aria-checked]");
  } catch (e) {
    return null;
  }
}

function findPlayButton(doc) {
  try {
    return doc.querySelector(SELECTORS.playPause);
  } catch (e) {
    return null;
  }
}

function hasVisibleAd(doc) {
  for (const selector of ['[data-testid="ad-slot"]', '[data-testid="advertisement"]']) {
    let ad = null;
    try {
      ad = doc.querySelector(selector);
    } catch (e) {
      continue;
    }
    try {
      if (ad && ad.getClientRects().length > 0) return true;
    } catch (e) {
      continue;
    }
  }
  return false;
}

// The now-playing bar carries data-testadtype="ad-type-none" for a track and
// "ad-type-ad" while an ad plays. The ad bar swap also renders the v2 widget.
// Use either signal so a stale track anchor can never resurrect an ad segment.
function readAdType(doc) {
  try {
    if (doc.querySelector(SELECTORS.adWidget)) return "ad";
  } catch (e) {
    return null;
  }
  let bar = null;
  try {
    bar = doc.querySelector(SELECTORS.adBar);
  } catch (e) {
    bar = null;
  }
  if (bar) {
    const value = attrOf(bar, "data-testadtype");
    if (value) return value === "ad-type-none" ? null : value;
  }
  return null;
}

function readPlayback(doc, wallMs) {
  if (hasVisibleAd(doc)) return null;
  const playBtn = findPlayButton(doc);
  const playing = attrOf(playBtn, "aria-label") === "Pause";
  if (readAdType(doc)) {
    return { kind: "ad", track: null, playing, wallMs, positionMs: 0, durationMs: 0 };
  }
  const track = readTrack(doc);
  const times = readTimes(doc);
  if (track && times && findLikeControl(doc)) {
    return { kind: "track", track, playing, wallMs, positionMs: times.positionMs, durationMs: times.durationMs };
  }
  if (!hasPlayer(doc)) return null;
  return { kind: "ad", track: null, playing, wallMs, positionMs: 0, durationMs: 0 };
}

function readLikeHint(doc) {
  const btn = findLikeControl(doc);
  if (!btn) return "unknown";
  return attrOf(btn, "aria-checked") === "false" ? "unliked" : "unknown";
}

class SoundedTimeSampler {
  constructor() {
    this.prev = null;
    // Playing-side wall clock and credited total implement the sounded-time
    // budget: progress credits against accumulated playing time, not against
    // a single tick gap. Spotify refreshes the progress bar in multi-second
    // steps in background tabs, so per-tick clipping structurally undercounts.
    this.playingWallMs = 0;
    this.creditedMs = 0;
  }

  reset() {
    this.prev = null;
    this.playingWallMs = 0;
    this.creditedMs = 0;
  }

  observe(sample) {
    if (!sample || sample.kind !== "track" || !sample.track || !sample.track.id || !(sample.durationMs > 0)) {
      this.reset();
      return 0;
    }
    const prev = this.prev;
    this.prev = sample;
    if (!prev || !prev.track || prev.track.id !== sample.track.id) {
      this.playingWallMs = 0;
      this.creditedMs = 0;
      return 0;
    }
    if (!prev.playing || !sample.playing) return 0;
    const wall = sample.wallMs - prev.wallMs;
    if (!(wall > 0)) return 0;
    this.playingWallMs += wall;
    const progress = sample.positionMs - prev.positionMs;
    if (!(progress > 0)) return 0;
    const delta = Math.min(progress, Math.max(0, this.playingWallMs - this.creditedMs));
    if (!(delta > 0)) return 0;
    this.creditedMs += delta;
    return delta;
  }
}

function findMenu(root) {
  try {
    return root.querySelector(SELECTORS.menu);
  } catch (e) {
    return null;
  }
}

function rowLabel(node) {
  try {
    return node && node.textContent ? node.textContent.trim() : "";
  } catch (e) {
    return "";
  }
}

function findLikedCheckbox(menu) {
  if (!menu) return null;
  let labeled = null;
  try {
    labeled = menu.querySelector(SELECTORS.likedRow);
  } catch (e) {
    labeled = null;
  }
  const fromClosest = labeled && labeled.closest
    ? labeled.closest('button[role="menuitemcheckbox"]')
    : null;
  if (fromClosest) return fromClosest;
  // Label-gated fallback: the labeled row is locale-proof, but when it is
  // missing only a row that names Liked Songs may be touched. Never fall
  // back to the first checkbox, which can belong to another playlist.
  let boxes = [];
  try {
    const list = menu.querySelectorAll('button[role="menuitemcheckbox"]');
    boxes = list ? Array.from(list) : [];
  } catch (e) {
    boxes = [];
  }
  return boxes.find((b) => rowLabel(b).toLowerCase().includes("liked songs")) || null;
}

function findDone(menu) {
  try {
    return menu.querySelector('button[type="submit"]');
  } catch (e) {
    return null;
  }
}

function clickCancel(menu) {
  let buttons = [];
  try {
    const list = menu.querySelectorAll("button");
    buttons = list ? Array.from(list) : [];
  } catch (e) {
    return;
  }
  const cancel = buttons.find((b) => (b.textContent || "").trim() === "Cancel");
  try {
    if (cancel && cancel.click) cancel.click();
  } catch (e) {
    // Menu cleanup is best-effort; the next read re-syncs state.
  }
}

class LikeToggle {
  constructor(root, opts) {
    this.root = root;
    this.settleMs = (opts && opts.settleMs) || 150;
    this.contentTimeoutMs = (opts && opts.contentTimeoutMs) || 2500;
    this.contentPollMs = (opts && opts.contentPollMs) || 100;
  }

  sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  mainButton() {
    try {
      return this.root.querySelector(SELECTORS.widget + " button[aria-checked]")
        || this.root.querySelector("button[aria-checked]");
    } catch (e) {
      return null;
    }
  }

  async openMenu() {
    const btn = this.mainButton();
    if (!btn) return null;
    try {
      btn.click();
    } catch (e) {
      return null;
    }
    await this.sleep(this.settleMs);
    return findMenu(this.root);
  }

  // Spotify fetches the playlist rows after the menu shell opens, so the
  // Liked Songs row is awaited with a bounded poll instead of assumed
  // present after one settle sleep.
  async waitForLiked(menu) {
    const started = Date.now();
    for (;;) {
      const box = findLikedCheckbox(menu);
      if (box) return box;
      if (Date.now() - started >= this.contentTimeoutMs) return null;
      await this.sleep(this.contentPollMs);
    }
  }

  async check() {
    if (readLikeHint(this.root) === "unliked") return "unliked";
    const menu = await this.openMenu();
    if (!menu) return "unknown";
    const box = await this.waitForLiked(menu);
    const state = !box
      ? "unknown"
      : attrOf(box, "aria-checked") === "true"
        ? "liked"
        : "unliked";
    clickCancel(menu);
    return state;
  }

  async save() {
    const state = await this.check();
    if (state === "liked") return { ok: true, action: "already-saved" };
    const btn = this.mainButton();
    if (!btn) return { ok: false, reason: "dom-changed" };
    if (attrOf(btn, "aria-checked") === "false") {
      try {
        btn.click();
      } catch (e) {
        return { ok: false, reason: "dom-changed" };
      }
      await this.sleep(this.settleMs);
      const flipped = this.mainButton();
      return attrOf(flipped, "aria-checked") === "true"
        ? { ok: true, action: "saved" }
        : { ok: false, reason: "confirm-mismatch" };
    }
    const menu = await this.openMenu();
    if (!menu) return { ok: false, reason: "menu-timeout" };
    const box = await this.waitForLiked(menu);
    if (!box) {
      clickCancel(menu);
      return { ok: false, reason: "menu-timeout" };
    }
    if (attrOf(box, "aria-checked") === "true") {
      clickCancel(menu);
      return { ok: true, action: "already-saved" };
    }
    try {
      box.click();
    } catch (e) {
      clickCancel(menu);
      return { ok: false, reason: "dom-changed" };
    }
    await this.sleep(this.settleMs);
    const done = findDone(menu);
    if (!done || !done.click) {
      clickCancel(menu);
      return { ok: false, reason: "dom-changed" };
    }
    try {
      done.click();
    } catch (e) {
      return { ok: false, reason: "dom-changed" };
    }
    await this.sleep(this.settleMs);
    return { ok: true, action: "saved" };
  }

  async remove() {
    const btn = this.mainButton();
    if (!btn) return { ok: false, reason: "dom-changed" };
    if (attrOf(btn, "aria-checked") === "false") return { ok: true, action: "removed" };
    const menu = await this.openMenu();
    if (!menu) {
      try {
        btn.click();
      } catch (e) {
        return { ok: false, reason: "dom-changed" };
      }
      await this.sleep(this.settleMs);
      return attrOf(this.mainButton(), "aria-checked") === "false"
        ? { ok: true, action: "removed" }
        : { ok: false, reason: "confirm-mismatch" };
    }
    const box = await this.waitForLiked(menu);
    if (!box) {
      clickCancel(menu);
      return { ok: false, reason: "menu-timeout" };
    }
    if (attrOf(box, "aria-checked") === "false") {
      clickCancel(menu);
      return { ok: true, action: "removed" };
    }
    try {
      box.click();
    } catch (e) {
      clickCancel(menu);
      return { ok: false, reason: "dom-changed" };
    }
    await this.sleep(this.settleMs);
    const done = findDone(menu);
    if (!done || !done.click) {
      clickCancel(menu);
      return { ok: false, reason: "dom-changed" };
    }
    try {
      done.click();
    } catch (e) {
      return { ok: false, reason: "dom-changed" };
    }
    await this.sleep(this.settleMs);
    return { ok: true, action: "removed" };
  }
}


// ---- extension/lib/toast.js ----
// In-page Undo toast (M6). Single-flight notice with a one-shot Undo
// button. The page owns display only; persistence lives in the background.

class UndoToast {
  constructor(root, opts) {
    this.root = root;
    this.timeoutMs = (opts && opts.timeoutMs) || 8000;
    this.el = null;
    this.timer = null;
  }

  dismiss() {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    try {
      if (this.el && this.el.remove) this.el.remove();
    } catch (e) {
      // Toast teardown is best-effort.
    }
    this.el = null;
  }

  show(track, onUndo) {
    this.dismiss();
    let el = null;
    try {
      el = this.root.createElement("div");
    } catch (e) {
      return;
    }
    if (!el) return;
    try {
      el.setAttribute("data-testid", "music-saver-toast");
    } catch (e) {
      // Attribute failure still leaves a usable notice.
    }
    try {
      el.setAttribute("role", "status");
    } catch (e) {
      // Usable without the hook.
    }
    try {
      if (el.style) {
        el.style.cssText =
          "display:block!important;position:fixed;bottom:96px;left:50%;transform:translateX(-50%);z-index:2147483647;" +
          "background:#191414;color:#fff;padding:10px 14px;border-radius:8px;" +
          "font:14px system-ui,sans-serif;box-shadow:0 4px 16px rgba(0,0,0,.4);";
      }
    } catch (e) {
      // An unstyled toast still carries the Undo action.
    }
    const text = (track ? track.title + " - " + track.artist : "Track") + " saved to Liked Songs";
    if ("textContent" in el) {
      el.textContent = text + " ";
    }
    let btn = null;
    try {
      btn = this.root.createElement("button");
    } catch (e) {
      btn = null;
    }
    if (!btn) return;
    try {
      btn.setAttribute("data-testid", "music-saver-undo");
    } catch (e) {
      // Usable without the hook.
    }
    btn.textContent = "Undo";
    let fired = false;
    const fire = () => {
      if (fired) return;
      fired = true;
      try {
        if (onUndo) onUndo();
      } finally {
        this.dismiss();
      }
    };
    try {
      if (btn.addEventListener) btn.addEventListener("click", fire);
      else btn.onclick = fire;
    } catch (e) {
      btn.onclick = fire;
    }
    try {
      if (el.appendChild) el.appendChild(btn);
      const host = this.root.body && this.root.body.appendChild ? this.root.body : this.root;
      if (host.appendChild) host.appendChild(el);
      else if (this.root.appendChild) this.root.appendChild(el);
    } catch (e) {
      return;
    }
    this.el = el;
    this.timer = setTimeout(() => this.dismiss(), this.timeoutMs);
  }
}



// ---- extension/content.js ----
// Content-script watcher (M2/M4/M6). The edge owns the decide-and-act
// loop: sample playback, feed sounded-only deltas into the eligibility
// tracker, and on the single eligible transition run one check-then-act
// Like transaction with an Undo toast. The background only persists the
// reported events. Testable with injected deps; the live wiring at the
// bottom runs solely on open.spotify.com inside the extension.

function makeNonce(trackId, kind, nowMs) {
  return trackId + ":" + kind + ":" + nowMs + ":" + Math.floor(Math.random() * 1e9);
}

class WatchLoop {
  constructor(opts) {
    this.read = opts.read;
    this.sampler = opts.sampler;
    this.likes = opts.likes;
    this.toast = opts.toast;
    this.tracker = opts.tracker;
    this.report = opts.report;
    this.settings = opts.settings;
    this.nowMs = opts.nowMs || (() => Date.now());
    this.pollMs = opts.pollMs || 1000;
    this.send = opts.send || null;
    this.timer = null;
    this.busy = false;
    this.lastPolledId = null;
    this.lastRetryPollMs = 0;
  }

  static create(opts) {
    const doc = opts.doc;
    const settings = normalizeSettings(opts.settings);
    return new WatchLoop({
      read: (wall) => readPlayback(doc, wall),
      sampler: new SoundedTimeSampler(),
      likes: new LikeToggle(doc, { settleMs: 200 }),
      toast: new UndoToast(doc),
      tracker: new EligibilityTracker(settings),
      report: (event) => opts.sendMessage({ type: "ms-event", event }),
      send: (msg) => opts.sendMessage(msg),
      settings,
      nowMs: opts.nowMs,
      pollMs: opts.pollMs,
    });
  }

  applySettings(next) {
    this.settings = normalizeSettings(next);
    this.tracker = new EligibilityTracker(this.settings);
    if (this.sampler) this.sampler.reset();
  }

  async tick() {
    if (!this.settings.enabled || this.busy) return null;
    const now = this.nowMs();
    let sample = null;
    try {
      sample = this.read(now);
    } catch (e) {
      this.sampler.reset();
      return null;
    }
    const delta = this.sampler.observe(sample);
    if (!sample || !sample.track || !(sample.durationMs > 0)) return null;
    if (sample.track.id !== this.lastPolledId) {
      this.lastPolledId = sample.track.id;
      this.lastRetryPollMs = now;
      await this.pollRetries(sample.track, now);
    } else if (now - this.lastRetryPollMs > 30000) {
      this.lastRetryPollMs = now;
      await this.pollRetries(sample.track, now);
    }
    if (!(delta > 0)) return null;
    let eligible = false;
    try {
      eligible = this.tracker.sound(sample.track.id, sample.durationMs, delta);
    } catch (e) {
      return null;
    }
    if (!eligible) return null;
    this.busy = true;
    try {
      return await this.handleEligible(sample.track, now);
    } finally {
      this.busy = false;
    }
  }

  async handleEligible(track, now) {
    let state = "unknown";
    try {
      state = await this.likes.check();
    } catch (e) {
      return this.fail(track, now, "save", "check-threw");
    }
    if (state === "liked") {
      return this.emit({ kind: "skip", track, now, detail: "already-liked" });
    }
    let out = null;
    try {
      out = await this.likes.save();
    } catch (e) {
      return this.fail(track, now, "save", "save-threw");
    }
    if (!out || !out.ok) {
      return this.fail(track, now, "save", (out && out.reason) || "save-failed");
    }
    if (out.action === "already-saved") {
      return this.emit({ kind: "skip", track, now, detail: "already-saved" });
    }
    const event = this.emit({ kind: "save", track, now, detail: "" });
    try {
      this.toast.show(track, () => {
        this.undo(track);
      });
    } catch (e) {
      // A toast failure never blocks the recorded save.
    }
    return event;
  }

  async undo(track) {
    const now = this.nowMs();
    let current = null;
    try {
      current = this.read(now);
    } catch (e) {
      current = null;
    }
    const currentId = current && current.track ? current.track.id : null;
    if (currentId !== track.id) {
      return this.fail(track, now, "remove", "track-changed");
    }
    let out = null;
    try {
      out = await this.likes.remove();
    } catch (e) {
      return this.fail(track, now, "remove", "remove-threw");
    }
    if (out && out.ok) {
      return this.emit({ kind: "undo", track, now, detail: "" });
    }
    return this.fail(track, now, "remove", (out && out.reason) || "remove-failed");
  }

  emit(opts) {
    const event = {
      nonce: makeNonce(opts.track.id, opts.kind, opts.now),
      ts: opts.now,
      kind: opts.kind,
      trackId: opts.track.id,
      uri: opts.track.uri,
      title: opts.track.title,
      artist: opts.track.artist,
      detail: opts.detail || "",
    };
    try {
      this.report(event);
    } catch (e) {
      // Reporting is best-effort; the local state already converged.
    }
    return event;
  }

  fail(track, now, intent, detail) {
    return this.emit({ kind: "fail", track, now, detail: intent + ":" + detail });
  }

  async pollRetries(track, now) {
    if (!this.send) return;
    let due = [];
    try {
      const res = await this.send({ type: "ms-due", trackId: track.id, nowMs: now });
      due = (res && res.due) || [];
    } catch (e) {
      return;
    }
    for (const intent of due) {
      let out = null;
      try {
        out = intent.kind === "remove" ? await this.likes.remove() : await this.likes.save();
      } catch (e) {
        out = null;
      }
      try {
        await this.send({ type: "ms-ack", id: intent.id, ok: !!(out && out.ok), nowMs: this.nowMs() });
      } catch (e) {
        // The intent stays queued; the next poll retries it.
      }
    }
  }

  start() {
    if (this.timer) return;
    this.timer = setInterval(() => {
      this.tick();
    }, this.pollMs);
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    try {
      if (this.toast) this.toast.dismiss();
    } catch (e) {
      // Teardown is best-effort.
    }
  }
}

// The shipped manifest matches only Spotify, so the loop boots there. The E2E
// runner patches a temp manifest to add loopback and serves the player fixture
// from it, so that host must boot too.
function shouldBoot(href) {
  let url;
  try {
    url = new URL(String(href || ""));
  } catch (e) {
    return false;
  }
  if (url.hostname === "open.spotify.com") return true;
  return url.protocol === "http:" && url.hostname === "127.0.0.1";
}

function liveBoot() {
  try {
    if (typeof document === "undefined") return;
    if (typeof chrome === "undefined" || !chrome.runtime || !chrome.runtime.sendMessage) return;
    if (!shouldBoot((typeof location !== "undefined" && location.href) || "")) return;
    const sendMessage = (msg) =>
      new Promise((resolve) => {
        try {
          chrome.runtime.sendMessage(msg, (res) => resolve(res));
        } catch (e) {
          resolve(null);
        }
      });
    const store = {
      load: async () => {
        try {
          return (await chrome.storage.local.get("settings")).settings;
        } catch (e) {
          return undefined;
        }
      },
    };
    Promise.resolve()
      .then(() => store.load())
      .then((raw) => {
        const loop = WatchLoop.create({ doc: document, sendMessage, settings: raw || {} });
        loop.start();
        try {
          const storageChanged = chrome.storage && chrome.storage.onChanged;
          if (storageChanged && storageChanged.addListener) {
            storageChanged.addListener((changes, area) => {
              if (area === "local" && changes && changes.settings) {
                try {
                  loop.applySettings(changes.settings.newValue);
                } catch (e) {
                  // Settings apply is best-effort at the edge.
                }
              }
            });
          }
        } catch (e) {
          // Live-reload is best-effort.
        }
      });
  } catch (e) {
    // Never break the host page.
  }
}

liveBoot();


